<script setup lang="ts">
import { ref, watch } from 'vue';
import type { Row } from '../../../shared/domain';
import { aiPrompts, useAiAssistant } from '../../../shared/useAiAssistant';
import { api } from '../platform';
const props = defineProps<{ user: Row | null }>();
const emit = defineEmits<{ (event: 'join'): void }>();
const { messages, draft, error, busy, loading, consent, available, demo, status, failed, allowed, full, canSend, load, clear, send, retry } = useAiAssistant(() => props.user, api);
const notice = ref('');
watch(() => props.user?.id, () => { notice.value = ''; });
function newConversation() { if (busy.value || loading.value) return;if (!messages.value.length && !draft.value) return clear();const identity = props.user?.id;uni.showModal({ title: '新建对话', content: '清空当前对话？对话不会保存，清空后无法恢复。', success: result => { if (result.confirm && identity === props.user?.id && !busy.value) { clear();notice.value = ''; } } }); }
function copy(text: string) { const identity = props.user?.id;uni.setClipboardData({ data: text, success: () => { if (identity === props.user?.id) notice.value = '回复已复制'; }, fail: () => { if (identity === props.user?.id) notice.value = '无法自动复制，请长按文字复制'; } }); }
</script>
<template><view class="ai-mobile">
  <view class="ai-heading"><view><view class="title">AI 助手</view><view class="intro">使用指引、问答与文案起草</view></view><button v-if="allowed" class="outline" :disabled="busy || loading" @click="newConversation">新建对话</button></view>
  <view v-if="!allowed" class="panel"><view class="card-title">让日常参与更轻松</view><view class="ai-note">登录并通过会员审核后即可提问。系统不会自动读取会员资料、订单或聊天记录。</view><button class="primary" @click="emit('join')">登录 / 查看入会状态</button></view>
  <template v-else><view class="ai-status"><view>{{ demo ? '演示模式 · 示例回复' : 'AI 智能问答' }}</view><view class="ai-note">{{ loading ? '正在连接助手…' : status }}</view><button class="text-button" :disabled="busy || loading" @click="load">刷新状态</button></view>
    <view class="ai-note">{{ demo ? '本机固定示例，不连接真实模型。' : '发送后，当前对话文字将交由已配置的模型服务处理。请勿填写密码、证件或联系方式等私密信息。' }} 对话仅在当前页面保留，离开即清空。回复请核实后使用。</view>
    <view class="ai-prompts"><button v-for="prompt in aiPrompts" :key="prompt" class="outline" :disabled="busy || !available || full" @click="draft = prompt">{{ prompt }}</button></view>
    <view class="ai-history"><view v-if="!messages.length && !busy" class="ai-note">写下你想解决的事情。助手提供建议和草稿，业务操作仍需你确认。</view><view v-for="(row,index) in messages" :key="index" class="ai-message" :class="row.role"><view class="ai-speaker">{{ row.role === 'user' ? '我' : row.demo ? '示例回复 · 非模型生成' : 'AI 助手' }}</view><text class="ai-content" selectable>{{ row.content }}</text><view v-if="row.truncated" class="ai-note">回复已达长度限制，可新建对话请助手分段说明。</view><button v-if="row.role === 'assistant'" class="text-button" @click="copy(row.content)">复制回复</button></view><view v-if="busy" class="ai-note">正在整理回复，请稍候…</view></view>
    <view v-if="notice" class="ai-note">{{ notice }}</view><view v-if="full" class="ai-note">当前对话已达长度上限，请新建对话。</view><view v-if="error" class="error">{{ error }}<button v-if="failed && draft.trim() === failed" class="text-button" :disabled="!canSend" @click="retry">重试本条</button></view>
    <view class="ai-composer"><text class="field-label">你的问题</text><textarea v-model="draft" :disabled="busy || !available || full" :maxlength="2000" placeholder="例如：帮我起草活动邀请，时间地点用占位符。"/><checkbox-group @change="consent = $event.detail.value.includes('agree')"><label class="ai-consent"><checkbox value="agree" :checked="consent" :disabled="busy || !available"/><text>{{ demo ? '我了解这是本机示例体验' : '我同意将当前对话文字发送给模型服务' }}</text></label></checkbox-group><view class="ai-note">{{ draft.length }} / 2000 · 最多5轮</view><button class="primary" :disabled="!canSend" @click="send">{{ busy ? '正在回复…' : '发送问题' }}</button></view>
  </template>
</view></template>
<style scoped>
.ai-mobile{color:var(--skin-text,#303133)}.ai-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:20rpx;margin:20rpx 0 30rpx}.ai-heading button{flex-shrink:0;margin:0;font-size:13px;padding:14rpx}.ai-note{font-size:13px;line-height:1.9;color:var(--skin-muted,#606266);margin:18rpx 0}.ai-status{padding:26rpx;background:var(--skin-soft,#ecf5ff);border:1px solid var(--skin-border,#dcdfe6);border-radius:20rpx;font-size:15px}.ai-status button{padding:0;text-align:left;margin:0;font-size:13px}.ai-prompts{display:grid;grid-template-columns:minmax(0,1fr);gap:16rpx;margin:24rpx 0}.ai-prompts button{margin:0;text-align:left;font-size:14px;line-height:1.7;padding:20rpx;white-space:normal}.ai-history{background:var(--skin-surface,#fff);border:1px solid var(--skin-border,#dcdfe6);padding:22rpx;border-radius:20rpx;min-height:160rpx}.ai-message{padding:24rpx;background:var(--skin-soft,#ecf5ff);border-radius:16rpx;margin-bottom:22rpx;overflow-wrap:anywhere}.ai-message.user{margin-left:30rpx;background:var(--skin-bg,#f5f7fa)}.ai-speaker{color:var(--skin-primary,#337ecc);font-size:13px;font-weight:600;margin-bottom:16rpx}.ai-content{display:block;white-space:pre-wrap;font-size:15px;line-height:1.9;word-break:break-word}.ai-message button{text-align:left;margin:16rpx 0 0;padding:0;font-size:13px}.ai-composer{margin-top:30rpx}.ai-composer textarea{box-sizing:border-box;width:100%;min-height:160px;height:160px;background:var(--skin-input,#fff);color:var(--skin-text,#303133);border:1px solid var(--skin-border,#dcdfe6)}.ai-consent{display:flex;align-items:flex-start;gap:12rpx;margin-top:20rpx;font-size:13px;line-height:1.8}.ai-consent checkbox{flex-shrink:0}.ai-mobile button{min-height:44px}.ai-mobile button[disabled]{opacity:.55}
</style>
